(* [comment removed for export] *)
Ltac csr_keeps_tac Hs :=
  unfold csr_keeps; destruct (csr_frmw _) eqn:CF; cbn [negb orb] in Hs |- *;
  rewrite ?orb_true_r; try reflexivity; try discriminate;
  try (rewrite Hs; reflexivity);
  try (match goal with |- context [bv_unsigned ?c =? 3] =>
         case_eq (bv_unsigned c =? 3); intros E3; rewrite E3 in *; cbn [orb] in Hs |- * end;
       [ rewrite (proj2 (Z.ltb_lt _ _) (zext5_lt32 _)); rewrite ?orb_true_r; reflexivity
       | rewrite zext5_land7, Hs; rewrite ?orb_true_r; reflexivity ]).

Lemma csr_keeps_reg : forall op rs1 operand csr,
  (negb (csr_frmw csr) || match op with CSR_RC => true | CSR_RS => is_x0 rs1 | CSR_RW => false end) = true ->
  csr_keeps op operand (match op with CSR_RW => true | _ => negb (is_x0 rs1) end) csr = true.
Proof.
  intros op rs1 operand csr. unfold csr_keeps.
  destruct op, (csr_frmw csr), (is_x0 rs1); cbn [negb orb];
    first [ intros _; reflexivity | intros Hf; discriminate Hf ].
Qed.

Lemma csr_keeps_imm : forall op (uimm : bv 5) csr,
  (negb (csr_frmw csr) || match op with CSR_RC => true | _ => (bv_unsigned csr =? 3) || (Z.land (bv_unsigned uimm) 7 =? 0) end) = true ->
  csr_keeps op (zext 64 uimm) (match op with CSR_RW => true | _ => negb (Z.eqb (bv_unsigned uimm) 0) end) csr = true.
Proof.
  intros op uimm csr. unfold csr_keeps. rewrite zext5_land7.
  pose proof (proj2 (Z.ltb_lt _ _) (zext5_lt32 uimm)) as Hlt.
  destruct op, (csr_frmw csr), (bv_unsigned csr =? 3), (Z.land (bv_unsigned uimm) 7 =? 0), (bv_unsigned uimm =? 0);
    cbn [negb orb];
    first [ intros _; reflexivity | intros Hf; discriminate Hf | intros _; exact Hlt ].
Qed.

Lemma exec_frm : forall sz i c, frm_safe i = true -> frm0 (c_fcsr c) ->
  eff_all (fun c' => frm0 (c_fcsr c')) (exec sz i c).
Proof.
  intros sz i [R F pc fc rv] Hs H0. cbn [c_fcsr] in H0.
  destruct i; cbn [frm_safe] in Hs; cbn [exec]; cbv zeta.
  all: try (destruct (csr_write_illegal _ _);
            [ exact I
            | apply exec_csr_frm;
              [ first [ apply csr_keeps_reg; exact Hs | apply csr_keeps_imm; exact Hs ] | exact H0 ] ]).
  all: frm_go H0.
Qed.
